package com.ironcore.entity;

import jakarta.persistence.*;
import java.time.LocalDateTime;

/**
 * Entity representing a fitness/gym program.
 * Stores program details including title, description, and image data.
 */
@Entity
@Table(name = "programs")
public class Program {

    // Primary key - auto-generated by database
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    // Program title - required, max 100 characters
    @Column(nullable = false, length = 100)
    private String title;

    // Program description - can be longer text
    @Column(columnDefinition = "TEXT")
    private String description;

    // Image filename - stores the original name of the uploaded image
    @Column(length = 255)
    private String imageName;

    // Image content type - stores MIME type (e.g., "image/jpeg", "image/png")
    @Column(length = 50)
    private String imageType;

    // Image data - stores the actual image bytes
    @Lob
    private byte[] imageData;

    // Program benefits - stored as comma-separated or JSON string
    @Column(columnDefinition = "TEXT")
    private String benefits;

    // Timestamps - automatically managed by Hibernate
    @Column(name = "created_at", updatable = false)
    private LocalDateTime createdAt;

    @Column(name = "updated_at")
    private LocalDateTime updatedAt;

    /**
     * Called before entity is first saved to database.
     * Sets createdAt and updatedAt to current time.
     */
    @PrePersist
    protected void onCreate() {
        createdAt = LocalDateTime.now();
        updatedAt = LocalDateTime.now();
    }

    /**
     * Called before entity is updated in database.
     * Updates updatedAt to current time.
     */
    @PreUpdate
    protected void onUpdate() {
        updatedAt = LocalDateTime.now();
    }

    // Default constructor required by JPA
    public Program() {}

    // ===== Getter and Setter Methods =====

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public String getTitle() {
        return title;
    }

    public void setTitle(String title) {
        this.title = title;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public String getImageName() {
        return imageName;
    }

    public void setImageName(String imageName) {
        this.imageName = imageName;
    }

    public String getImageType() {
        return imageType;
    }

    public void setImageType(String imageType) {
        this.imageType = imageType;
    }

    public byte[] getImageData() {
        return imageData;
    }

    public void setImageData(byte[] imageData) {
        this.imageData = imageData;
    }

    public String getBenefits() {
        return benefits;
    }

    public void setBenefits(String benefits) {
        this.benefits = benefits;
    }

    public LocalDateTime getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(LocalDateTime createdAt) {
        this.createdAt = createdAt;
    }

    public LocalDateTime getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(LocalDateTime updatedAt) {
        this.updatedAt = updatedAt;
    }
}